package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Closed unchanged-original VEP/LOFTEE settings and explicit input/resource identities. */
final class LofteeWorkflowRequest {
    private LofteeWorkflowRequest() { }
    static final String PROFILE="original-VEP105.0-LOFTEE-GRCh38-Linux-x86_64";
    record Request(String edition,Path vcf,String inputCompression,Map<String,Object> transcripts,Map<String,Object> fasta,
                   Map<String,Object> gerp,Map<String,Object> ancestor,Map<String,Object> conservation,
                   Map<String,Path> runtime,String referenceOrigin,List<Map<String,Object>> analyses,Path out,
                   long inputBytes,long resourceBytes,long decodedCharacters,long variants,long annotations,
                   int lineCharacters,long outputBytes,int outputFiles,long timeoutMillis,int threads,int bufferSize) {
        Map<String,Path> files(){
            var result=new LinkedHashMap<String,Path>();result.put(inputName(),vcf);addFasta(result,"reference",fasta);
            if(transcripts.get("kind").equals("gtf")){result.put("genes.gtf.gz",Path.of(textUnchecked(transcripts.get("file"))));result.put("genes.gtf.gz.tbi",Path.of(textUnchecked(transcripts.get("index"))));}
            if(gerp.get("kind").equals("bigwig"))result.put("gerp.bw",Path.of(textUnchecked(gerp.get("file"))));
            if(ancestor.get("kind").equals("fasta"))addFasta(result,"ancestor",ancestor);
            if(conservation.get("kind").equals("sqlite"))result.put("conservation.sqlite",Path.of(textUnchecked(conservation.get("file"))));return result;
        }
        String inputName(){return inputCompression.equals("gzip")?"input.vcf.gz":"input.vcf";}
        private static String textUnchecked(Object x){return (String)x;}
        private static void addFasta(Map<String,Path> target,String name,Map<String,Object> config){String suffix=config.get("compression").equals("bgzip")?".fa.gz":".fa";target.put(name+suffix,Path.of(textUnchecked(config.get("file"))));target.put(name+suffix+".fai",Path.of(textUnchecked(config.get("index"))));if(config.get("compression").equals("bgzip"))target.put(name+suffix+".gzi",Path.of(textUnchecked(config.get("gzi"))));}
        String fastaName(String name,Map<String,Object> config){return name+(config.get("compression").equals("bgzip")?".fa.gz":".fa");}
        Map<String,Object> effective(){var m=new LinkedHashMap<String,Object>();m.put("schema_version",1);m.put("mode","ANALYZE");m.put("profile",PROFILE);m.put("edition",edition);m.put("input_vcf",vcf.toString());m.put("input_compression",inputCompression);m.put("transcripts",transcripts);m.put("fasta",fasta);m.put("gerp",gerp);m.put("ancestor",ancestor);m.put("conservation",conservation);m.put("reference_origin",referenceOrigin);var paths=new LinkedHashMap<String,String>();runtime.forEach((k,v)->paths.put(k,v.toString()));m.put("runtime",paths);m.put("analyses",analyses);m.put("out",out.toString());m.put("maximum_input_bytes",inputBytes);m.put("maximum_resource_bytes",resourceBytes);m.put("maximum_decoded_characters",decodedCharacters);m.put("maximum_variants",variants);m.put("maximum_annotations",annotations);m.put("maximum_line_characters",lineCharacters);m.put("maximum_output_bytes",outputBytes);m.put("maximum_output_files",outputFiles);m.put("timeout_millis",timeoutMillis);m.put("threads",threads);m.put("buffer_size",bufferSize);return m;}
    }
    static Request parse(Map<String,Object> m,Path parent)throws IOException {
        fields(m,"schema_version","mode","profile","edition","input_vcf","input_compression","transcripts","fasta","gerp","ancestor","conservation","reference_origin","runtime","analyses","out","maximum_input_bytes","maximum_resource_bytes","maximum_decoded_characters","maximum_variants","maximum_annotations","maximum_line_characters","maximum_output_bytes","maximum_output_files","timeout_millis","threads","buffer_size");
        integer(m.get("schema_version"),1,1);require(choice(m.get("mode"),"ANALYZE").equals("ANALYZE"),"Declare analysis mode");require(text(m.get("profile")).equals(PROFILE),"Require the exact original VEP105/LOFTEE runtime profile; no paper-version substitution");String edition=choice(m.get("edition"),"grch38-1.0.4","cited-fork-c8fdde00");String origin=choice(m.get("reference_origin"),"supplied-reference","synthetic-controls");
        var fasta=fasta(object(m.get("fasta")),parent,false);var tr=object(m.get("transcripts"));String kind=choice(tr.get("kind"),"gtf","vep-cache");String assembly=assembly(tr.get("assembly_label"));require(assembly.equals(fasta.get("assembly_label")),"Transcript/FASTA assembly labels differ; no build conversion is inferred");label(tr.get("release_label"));
        if(kind.equals("gtf")){fields(tr,"kind","file","index","assembly_label","release_label");file(tr,"file",parent);file(tr,"index",parent);}
        else{fields(tr,"kind","directory","assembly_label","release_label","cache_version","species","cache_trust");integer(tr.get("cache_version"),105,105);choice(tr.get("species"),"homo_sapiens");choice(tr.get("cache_trust"),"trusted-original-ensembl-cache");file(tr,"directory",parent);require(assembly.equals("GRCh38"),"The captured human VEP105 cache profile requires the declared GRCh38 assembly; do not relabel an old cache");}
        var gerp=object(m.get("gerp"));if(choice(gerp.get("kind"),"not-applied","bigwig").equals("not-applied"))fields(gerp,"kind");else{fields(gerp,"kind","file","assembly_label","release_label");require(assembly(gerp.get("assembly_label")).equals(assembly),"GERP/FASTA assembly labels differ");label(gerp.get("release_label"));file(gerp,"file",parent);}
        var ancestor=object(m.get("ancestor"));if(choice(ancestor.get("kind"),"source-disabled","fasta").equals("source-disabled"))fields(ancestor,"kind");else{ancestor=fasta(ancestor,parent,true);require(ancestor.get("assembly_label").equals(assembly),"Ancestral/FASTA assembly labels differ");}
        var conservation=object(m.get("conservation"));if(choice(conservation.get("kind"),"source-disabled","sqlite").equals("source-disabled"))fields(conservation,"kind");else{fields(conservation,"kind","file","assembly_label","release_label");require(assembly(conservation.get("assembly_label")).equals(assembly),"Conservation/FASTA assembly labels differ");label(conservation.get("release_label"));file(conservation,"file",parent);}
        var rt=object(m.get("runtime"));fields(rt,"environment","bioperl","source");var runtime=new LinkedHashMap<String,Path>();for(String key:List.of("environment","bioperl","source"))runtime.put(key,path(rt,key,parent));
        var cases=new ArrayList<Map<String,Object>>();var ids=new HashSet<String>();boolean weighted=false,ancestral=false,conserved=false;
        for(Object raw:list(m.get("analyses"))){
            require(cases.size()<8,"Require1..8 original cases per atomic batch");var a=object(raw);fields(a,"id","settings","ancestral_check","conservation_check","complete_cds_check");String id=text(a.get("id"));require(id.matches("[A-Za-z][A-Za-z0-9_-]{0,63}")&&ids.add(id.toLowerCase(Locale.ROOT)),"Require unique portable case-insensitive case IDs");var s=object(a.get("settings"));fields(s,"min_intron_size","fast_length_calculation","use_gerp_end_trunc","gerp_end_trunc_cutoff","filter_position","get_splice_features","run_splice_predictions","weak_donor_cutoff","donor_disruption_mes_cutoff","acceptor_disruption_mes_cutoff","donor_disruption_cutoff","acceptor_disruption_cutoff","max_scan_distance","donor_rescue_cutoff","acceptor_rescue_cutoff","exonic_denovo_only","max_denovo_donor_distance","denovo_donor_cutoff","sre_flanksize","apply_all");
            var settings=new LinkedHashMap<String,Object>();settings.put("min_intron_size",number(s,"min_intron_size",15,1,100000));settings.put("fast_length_calculation",s.containsKey("fast_length_calculation")?choice(s.get("fast_length_calculation"),"fast","slow"):"fast");
            for(var entry:Map.of("use_gerp_end_trunc",true,"get_splice_features",true,"run_splice_predictions",false,"exonic_denovo_only",true,"apply_all",false).entrySet())settings.put(entry.getKey(),s.containsKey(entry.getKey())?bool(s.get(entry.getKey())):entry.getValue());
            for(var entry:Map.of("gerp_end_trunc_cutoff",-58.0,"filter_position",.05,"weak_donor_cutoff",-4.0,"donor_disruption_mes_cutoff",6.0,"acceptor_disruption_mes_cutoff",7.0,"donor_disruption_cutoff",.98,"acceptor_disruption_cutoff",.99,"donor_rescue_cutoff",8.5,"acceptor_rescue_cutoff",8.5,"denovo_donor_cutoff",.995).entrySet()){String key=entry.getKey();double lo=Set.of("filter_position","donor_disruption_cutoff","acceptor_disruption_cutoff","denovo_donor_cutoff").contains(key)?0:-1000000;double hi=lo==0?1:1000000;settings.put(key,s.containsKey(key)?finite(s.get(key),lo,hi):entry.getValue());}
            settings.put("max_scan_distance",number(s,"max_scan_distance",15,1,100000));settings.put("max_denovo_donor_distance",number(s,"max_denovo_donor_distance",200,1,100000));settings.put("sre_flanksize",number(s,"sre_flanksize",100,1,100000));boolean hasWeighted=(Boolean)settings.get("use_gerp_end_trunc");weighted|=hasWeighted;
            if(!(Boolean)settings.get("run_splice_predictions"))for(String key:List.of("get_splice_features","weak_donor_cutoff","donor_disruption_mes_cutoff","acceptor_disruption_mes_cutoff","donor_disruption_cutoff","acceptor_disruption_cutoff","max_scan_distance","donor_rescue_cutoff","acceptor_rescue_cutoff","exonic_denovo_only","max_denovo_donor_distance","denovo_donor_cutoff","sre_flanksize"))require(!s.containsKey(key),"Extended splice setting is not applied when run_splice_predictions=false: "+key);
            if(hasWeighted)require(!s.containsKey("filter_position"),"Percentile filter_position is not applied in the selected original GERP branch");else require(!s.containsKey("gerp_end_trunc_cutoff"),"GERP cutoff is not applied in the selected original percentile branch");
            boolean anc=bool(a.get("ancestral_check")),cons=bool(a.get("conservation_check"));ancestral|=anc;conserved|=cons;if(anc)require(ancestor.get("kind").equals("fasta"),"Ancestral checking requires the supplied exact ancestral FASTA/index");if(cons)require(conservation.get("kind").equals("sqlite"),"Conservation checking requires the supplied exact local SQLite resource");choice(a.get("complete_cds_check"),"source-disabled");a.put("settings",Collections.unmodifiableMap(settings));cases.add(Collections.unmodifiableMap(a));
        }
        require(!cases.isEmpty(),"Require1..8 original cases");require(weighted==gerp.get("kind").equals("bigwig"),"Declare GERP only when at least one case applies it; no missing or unused resource is inferred");require(ancestral==ancestor.get("kind").equals("fasta"),"Supplied ancestral resource must be applied by at least one case");require(conserved==conservation.get("kind").equals("sqlite"),"Supplied conservation resource must be applied by at least one case");
        int threads=(int)number(m,"threads",1,1,64);require(!conserved||threads==1,"Original SQLite conservation state is shared across forked workers; select threads=1 for an applied conservation database, rather than silently losing calls/flags");
        return new Request(edition,path(m,"input_vcf",parent),choice(m.get("input_compression"),"none","gzip"),Map.copyOf(tr),Map.copyOf(fasta),Map.copyOf(gerp),Map.copyOf(ancestor),Map.copyOf(conservation),Map.copyOf(runtime),origin,List.copyOf(cases),path(m,"out",parent),number(m,"maximum_input_bytes",8589934592L,1,137438953472L),number(m,"maximum_resource_bytes",68719476736L,1,2199023255552L),number(m,"maximum_decoded_characters",34359738368L,1,2199023255552L),number(m,"maximum_variants",10000000,1,100000000),number(m,"maximum_annotations",100000000,1,1000000000),(int)number(m,"maximum_line_characters",2097152,256,33554432),number(m,"maximum_output_bytes",17179869184L,1,2199023255552L),(int)number(m,"maximum_output_files",100000,1,1000000),number(m,"timeout_millis",1800000,1,604800000),threads,(int)number(m,"buffer_size",5000,1,100000));
    }
    static boolean bool(Object x)throws IOException{require(x instanceof Boolean,"Require an explicit JSON boolean");return (Boolean)x;}
    static void fields(Map<String,Object> m,String... keys)throws IOException{var allowed=Set.of(keys);for(String key:m.keySet())require(allowed.contains(key),"Unknown LOFTEE field: "+key);}
    static String choice(Object x,String... values)throws IOException{String s=text(x);require(Set.of(values).contains(s),"Choose one of "+String.join(", ",values));return s;}
    private static String assembly(Object x)throws IOException{String s=label(x);require(s.matches("[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}"),"Use an explicit portable assembly label; no reference/build inference");return s;}
    private static Path path(Map<String,Object> m,String key,Path parent)throws IOException{return resolve(parent,label(m.get(key)));}
    private static void file(Map<String,Object> m,String key,Path parent)throws IOException{m.put(key,path(m,key,parent).toString());}
    private static Map<String,Object> fasta(Map<String,Object> m,Path parent,boolean kind)throws IOException {
        fields(m,"kind","file","index","compression","gzi","assembly_label","release_label");if(kind)choice(m.get("kind"),"fasta");else require(!m.containsKey("kind"),"Main FASTA uses explicit file/compression fields");String compression=choice(m.get("compression"),"none","bgzip");assembly(m.get("assembly_label"));label(m.get("release_label"));file(m,"file",parent);file(m,"index",parent);if(compression.equals("bgzip"))file(m,"gzi",parent);else require(!m.containsKey("gzi"),"Uncompressed FASTA must not carry an unapplied GZI");return m;
    }
}
